#!/usr/bin/env bash
# Every _shared helper that writes bytes to Storage must validate the file magic bytes first
# (doc 20 §20.4, PR-016), unless the bytes are server-generated/copied and listed below.
#
# Why a guard: the checklist was stale ("remaining upload paths") and each new upload helper
# copied the shape of the previous one. A new helper without a sniff fails CI instead of
# shipping a client-Content-Type trust path.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"

ALLOWLIST=(
  # Provider- or server-generated bytes (Gemini/Polotno/job output), never client-supplied.
  '_shared/marketingMediaIngest.ts'
  '_shared/marketingGenerationStorage.ts'
  '_shared/marketingTemplateThumbnails.ts'
  # Server-side copy of an object that was already validated when it was first uploaded.
  '_shared/propertyAssetClone.ts'
  # Unused legacy generic helper (no importers). Remove it rather than route bytes through it.
  '_shared/storageUpload.ts'
)

fail=0
while IFS= read -r file; do
  case "$file" in
    *_test.ts) continue ;;
  esac
  rel="${file#supabase/functions/}"
  allowed=0
  for entry in "${ALLOWLIST[@]}"; do
    if [[ "$rel" == "$entry" ]]; then
      allowed=1
      break
    fi
  done
  [[ "$allowed" -eq 1 ]] && continue

  # Any of the shared sniffers counts; a module may own a typed sniff (e.g. audio).
  if grep -Eq 'sniff[A-Za-z]*Mime|assertUploadMatchesBytes|assertMimeMatchesBytes' "$file"; then
    continue
  fi

  echo "MISSING magic-byte validation: $file" >&2
  fail=1
done < <(grep -rl '\.upload(' supabase/functions/_shared --include='*.ts' | sort)

if [[ "$fail" -ne 0 ]]; then
  exit 1
fi

echo "OK — every Storage writer validates magic bytes or is allowlisted."
